print("=== ContainerLab2 Loader - Decoded Strings ===")
print("")

local decoded = {}
for i, entry in ipairs(entries) do
    -- Loader field order: index marker, checksum, encoded bytes, operations, reverse flag.
    local idx_val, checksum, encoded, key_ops, reverse_flag = entry[1], entry[2], entry[3], entry[4], entry[5]
    
    -- Compute the index
    local transformed
    if idx_val == 22 then
        transformed = key_val - 158
    elseif idx_val == 219 then
        transformed = key_val + 114
    else
        transformed = bit32.bxor(key_val, 64783)
    end
    
    local lookup_idx = ((transformed - 7870 - 1) % 93) + 1
    
    local result = decodeString(encoded, key_ops, reverse_flag, checksum)
    if result then
        print(string.format("[%2d] (idx=%d lookup=%d) = %s", i, idx_val, lookup_idx, result))
        decoded[lookup_idx] = result
    else
        print(string.format("[%2d] (idx=%d lookup=%d) = [CHECKSUM MISMATCH]", i, idx_val, lookup_idx))
    end
end

print("")
print("=== Lookup Table (index -> string) ===")
for i = 1, 93 do
    if decoded[i] then
        print(string.format("  [%2d] %s", i, decoded[i]))
    else
        print(string.format("  [%2d] (not present in extracted table)", i))
    end
end
